class Component extends DCLogic {
  state = {
    panels: { settings: true, logs: true, lifetime: true, connlog: true, misc: true },
    expanded: { primaryavm: true, newfolder: true, newfeeder: true, sg: true, section1: true },
    selected: 'R2',
    pwOn: true,
    pwShow: false,
    readAll: false,
    iface: 'Ethernet',
    ifaceOpen: false,
    localConnected: null,
  };

  renderVals() {
    const s = this.state;
    const accent = this.props.accent || '#4772b3';
    const connected = s.localConnected !== null ? s.localConnected : !!this.props.connected;
    const selStyle = this.props.selectionStyle || 'Pill';
    const pill = selStyle === 'Pill';

    const defs = [
      { id: 'osnovnaya', label: 'Основная', level: 0, type: 'db' },
      { id: 'primarywer', label: 'Primarywer', level: 0, type: 'db' },
      { id: 'primaryavm', label: 'Primaryавм', level: 0, type: 'db', exp: 'primaryavm' },
      { id: 'newfolder', label: 'New Folder', level: 1, type: 'folder', parent: 'primaryavm', exp: 'newfolder' },
      { id: 'newfeeder', label: 'New Feeder', level: 2, type: 'feeder', parent: 'newfolder', exp: 'newfeeder' },
      { id: 'R1', label: 'R1', level: 3, type: 'recloser', parent: 'newfeeder' },
      { id: 'R2', label: 'R2', level: 3, type: 'recloser', parent: 'newfeeder' },
      { id: 'sg', label: 'SG', level: 2, type: 'sg', parent: 'newfolder', exp: 'sg' },
      { id: 'section1', label: 'Section 1', level: 3, type: 'section', parent: 'sg', exp: 'section1' },
      { id: 'MI', label: 'MI', level: 4, type: 'meter', parent: 'section1' },
      { id: 'RI', label: 'RI', level: 4, type: 'meter', parent: 'section1' },
      { id: 'OF2', label: 'OF 2', level: 4, type: 'meter', parent: 'section1' },
      { id: 'OF3', label: 'OF 3', level: 4, type: 'meter', parent: 'section1' },
      { id: 'OF4', label: 'OF 4', level: 4, type: 'meter', parent: 'section1' },
    ];
    const byId = {};
    defs.forEach(d => { byId[d.id] = d; });
    const visible = (d) => {
      let p = d.parent;
      while (p) { const pd = byId[p]; if (pd.exp && !s.expanded[pd.exp]) return false; p = pd.parent; }
      return true;
    };

    const rows = defs.filter(visible).map(d => {
      const sel = s.selected === d.id;
      const open = d.exp ? !!s.expanded[d.exp] : false;
      return {
        id: d.id,
        label: d.label,
        padLeft: (5 + d.level * 15) + 'px',
        hasToggle: !!d.exp,
        expKey: d.exp || '',
        rot: open ? 'rotate(90deg)' : 'rotate(0deg)',
        rowBg: sel && !pill ? accent : 'transparent',
        pillBg: sel && pill ? accent : 'transparent',
        pillRad: pill ? '4px' : '0px',
        pillPadR: pill ? '9px' : '3px',
        txt: sel ? '#ffffff' : '#cfcfcf',
        ico: sel ? '#ffffff' : '#a7afba',
        isDb: d.type === 'db', isFolder: d.type === 'folder', isFeeder: d.type === 'feeder',
        isRecloser: d.type === 'recloser', isSg: d.type === 'sg', isSection: d.type === 'section', isMeter: d.type === 'meter',
      };
    });

    const rot = (o) => o ? 'rotate(90deg)' : 'rotate(0deg)';

    return {
      accentVar: accent,
      logfg: connected ? '#cfcfcf' : '#6b6b6b',
      logico: connected ? '#9aa0aa' : '#565656',
      logsHint: connected ? '' : 'no data',

      rows,
      selectNode: (e) => { const id = e.currentTarget.getAttribute('data-id'); this.setState({ selected: id }); },
      toggleExp: (e) => {
        e.stopPropagation();
        const k = e.currentTarget.getAttribute('data-exp');
        if (k) this.setState(st => ({ expanded: { ...st.expanded, [k]: !st.expanded[k] } }));
      },

      pSettings: s.panels.settings, pLogs: s.panels.logs, pLifetime: s.panels.lifetime, pConnlog: s.panels.connlog, pMisc: s.panels.misc,
      rotSettings: rot(s.panels.settings), rotLogs: rot(s.panels.logs), rotLifetime: rot(s.panels.lifetime), rotConnlog: rot(s.panels.connlog), rotMisc: rot(s.panels.misc),
      togglePanel: (e) => {
        const n = e.currentTarget.getAttribute('data-panel');
        this.setState(st => ({ panels: { ...st.panels, [n]: !st.panels[n] } }));
      },

      pwOn: s.pwOn, pwShow: s.pwShow, readAll: s.readAll,
      pwBoxBg: s.pwOn ? accent : '#262626',
      readBoxBg: s.readAll ? accent : '#262626',
      togglePw: () => this.setState(st => ({ pwOn: !st.pwOn })),
      togglePwShow: () => this.setState(st => ({ pwShow: !st.pwShow })),
      toggleReadAll: () => this.setState(st => ({ readAll: !st.readAll })),
      pwValue: s.pwShow ? 'admin12' : '••••••',

      iface: s.iface, ifaceOpen: s.ifaceOpen,
      toggleIface: () => this.setState(st => ({ ifaceOpen: !st.ifaceOpen })),
      setIface: (e) => { const v = e.currentTarget.getAttribute('data-val'); this.setState({ iface: v, ifaceOpen: false }); },

      connected, notConnected: !connected,
      toggleConnect: () => this.setState(st => ({ localConnected: !(st.localConnected !== null ? st.localConnected : !!this.props.connected) })),
      dotColor: connected ? '#5cb85c' : '#cf5b4f',
      connectLabel: connected ? 'Disconnect' : 'Connect',
      statusText: connected ? 'Connected' : 'Disconnected',
      coVal: connected ? '12' : '—',
      wearVal: connected ? '8 %' : '—',
      battVal: connected ? '4.2 y' : '—',
    };
  }
}

