  coVal: connected ? '12' : '—',
  wearVal: connected ? '8 %' : '—',
  battVal: connected ? '4.2 y' : '—',
};

input.d_replace:
  coVal: connected ? '12' : '—',
  wearVal: connected ? '8 %' : '—',
  battVal: connected ? '4.2 y' : '—',

  logEntries: (connected ? [
    { dt: '29.06.2026 0:59:07', isError: false, msg: 'Connecting to 192.168.102.11:9001 …' },
    { dt: '29.06.2026 0:59:08', isError: false, msg: 'Socket established, negotiating protocol' },
    { dt: '29.06.2026 0:59:08', isError: true,  msg: 'Authentication attempt 1 failed: timeout' },
    { dt: '29.06.2026 0:59:09', isError: false, msg: 'Authenticated as admin' },
    { dt: '29.06.2026 0:59:09', isError: false, msg: 'Reading device info … CM15 v76.01.23' },
    { dt: '29.06.2026 0:59:10', isError: false, msg: 'Connected.' },
  ] : []).map((e, i) => ({
    dt: e.dt, msg: e.msg, isError: e.isError, notError: !e.isError,
    msgColor: e.isError ? '#d98a82' : '#c4c4c4',
    rowBg: i % 2 === 1 ? 'rgba(255,255,255,0.022)' : 'transparent',
  })),
};
